toolCalls.args:
{"command": "cd /tmp/symbols

# Let's get a better resolution - find the closest preceding symbol for each address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo -n "pc $addr -> "
  nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk -v target="$addr" '
    BEGIN { addr=strtonum(target); best_name="??"; best_addr=0 }
    { 
      sym_addr = strtonum("0x" $1)
      if (sym_addr <= addr && sym_addr > best_addr) {
        best_addr = sym_addr
        best_name = $3
        best_offset = addr - sym_addr
      }
    }
    END { printf "%s+0x%x (base: 0x%x)\n", best_name, best_offset, best_addr }
  '
done

echo ""
echo "=== Trying to install dotnet-symbol tool ==="
pip install --quiet dotnet-symbol 2>/dev/null || echo "Not available via pip"
which dotnet-symbol 2>/dev/null || echo "dotnet-symbol not found"
which dotnet 2>/dev/null && dotnet tool list -g 2>/dev/null | head -5", "description": "Better symbol resolution"}
